# 29  (V) numbers in the main text that had no primary source in the workspace; (D) benchmark started after the last thinning removal. No identifier is printed.
source("scripts/28_common.R")
cat("\n(V1) increment frame by origin and interval length\n"); print(d[, .(intervals = .N, plots = uniqueN(pid), inst = uniqueN(paste(Data, Install))), by = planted]); cat("all: plots", uniqueN(d$pid), "installations", uniqueN(paste(d$Data, d$Install)), "\n")
print(d[, .(n = .N), by = .(planted, len = cut(yip, c(0, 3, 9, 100), labels = c("1 to 3", "4 to 9", "over 9")))][order(planted, len)])
span <- d[, .(first = min(Measure), last = max(e_Measure), n = .N), by = .(pid, planted, Data)][, yrs := last - first]; cat("planted plots: record length in the increment frame, by source\n"); print(span[planted == 1, .(plots = .N, intervals = sum(n), max_years = max(yrs)), by = Data]); print(span[planted == 1][order(-yrs)][1:3, .(yrs, n)])
cat("natural intervals with yip 4 to 9:", d[planted == 0 & yip >= 4 & yip <= 9, .N], "of", d[planted == 0, .N], "; planted intervals with yip 1 to 3:", d[planted == 1 & yip <= 3, .N], "of", d[planted == 1, .N], "\n")
cat("\n(V2) BYI percentiles (10, 50, 90) by origin\n"); u <- unique(tr[, .(pid, planted, BYI, Data)]); print(u[, .(plots = .N, q10 = quantile(BYI, .1), q50 = quantile(BYI, .5), q90 = quantile(BYI, .9), min = min(BYI), max = max(BYI)), by = planted])
cat("type 7 against other quantile types, natural median:", paste(sapply(c(1, 4, 6, 7, 8), function(t) round(quantile(u[planted == 0, BYI], .5, type = t), 1)), collapse = " "), "\n")
ui <- unique(d[, .(pid, planted, BYI)]); cat("over increment-frame plots only:\n"); print(ui[, .(plots = .N, q10 = quantile(BYI, .1), q50 = quantile(BYI, .5), q90 = quantile(BYI, .9)), by = planted])
um <- M[, .(pid, planted, BYI)]; cat("over plots with a plot SDImax:\n"); print(um[, .(plots = .N, q10 = quantile(BYI, .1), q50 = quantile(BYI, .5), q90 = quantile(BYI, .9)), by = planted])
cat("natural plots by source, with the share at BYI 64 to 65:\n"); print(u[planted == 0, .(plots = .N, at64 = sum(BYI >= 64 & BYI < 65.01), byi_min = round(min(BYI), 1), byi_med = round(median(BYI), 1)), by = Data])
cat("\n(V3) height: held-out file and tallest trees\n"); if (file.exists("out/E2_cv.csv")) { e <- fread("out/E2_cv.csv"); print(names(e)); print(nrow(e)) }; print(f$hd[, .(trees = .N, plots = uniqueN(pid), tallest = max(HT)), by = planted]); cat("trees", nrow(f$hd), "plots", uniqueN(f$hd$pid), "\n")
cat("\n(D) benchmark started at the first visit at or after the last thinning removal of a thinned installation\n")
last_rem <- REM[, .(yr = max(yr)), by = .(Data, Install)]; tp <- unique(tr[, .(pid, Data, Install = as.character(Install))]); tp <- merge(tp, last_rem, by = c("Data", "Install"))
sv <- merge(tr[Status == "live" & !is.na(DBH) & DBH > 0, .(n = .N), by = .(pid, Measure)][n >= 5], tp[, .(pid, yr)], by = "pid")[Measure >= yr][, .SD[which.min(Measure)], by = pid]
pinfo2 <- function(i) { p <- sv$pid[i]; m0 <- sv$Measure[i]; L <- tr[pid == p & Measure == m0 & Status == "live" & !is.na(DBH) & DBH > 0]; L[is.na(HT) | HT < 1.37, HT := koa_height(DBH, cf)]; later <- sort(unique(tr[pid == p & Measure > m0, Measure])); if (nrow(f$srep[pid == p & Measure >= m0])) later <- later[later <= min(f$srep[pid == p & Measure >= m0, Measure])]
  if (!length(later)) return(NULL); obs <- rbindlist(lapply(later, function(m1) { ob <- merge(tr[pid == p & Measure == m1 & uid %in% L$uid & Status == "live", .(uid, DBH_c)], L[, .(uid, EXPF_c)], by = "uid"); if (!nrow(ob)) return(NULL); data.table(h = m1 - m0, o_surv = sum(ob$EXPF_c) / sum(L$EXPF_c), o_qmd = sqrt(sum(ob$DBH_c^2 * ob$EXPF_c) / sum(ob$EXPF_c)), o_ba = sum(0.00007854 * ob$DBH_c^2 * ob$EXPF_c)) }))
  if (!nrow(obs)) return(NULL); list(p = p, L = L, pl = L$planted[1], byi = L$BYI[1], obs = obs, n0 = nrow(L), N0 = sum(L$EXPF_c)) }
PI0 <- PI; PI <- Filter(Negate(is.null), lapply(seq_len(nrow(sv)), pinfo2)); cat("thinned installations with removal years:", nrow(last_rem), "; plots with a start visit at or after the last removal:", nrow(sv), "; with a later visit:", length(PI), "\n")
if (length(PI)) { bt <- benchrun(function(x) list(sm = SMO[[x$p]], bg = bg, bm = bm)); print(cbind(set = "after thinning", sm1(bt))); print(bt[, .(n = .N, plots = uniqueN(pid)), by = .(horizon = cut(h, c(0, 2, 5, 10, 100)))]); cat("start QMD and stems of these plots (median): QMD", round(median(sapply(PI, function(x) sqrt(sum(x$L$DBH^2 * x$L$EXPF_c) / x$N0))), 1), " stems per ha", round(median(sapply(PI, `[[`, "N0"))), "; planted share", mean(sapply(PI, `[[`, "pl")), "\n")
  last <- bt[, .SD[which.max(h)], by = pid]; cols <- c("bias_rel", "slope", "b1_lo", "b1_hi", "pass_int", "pass_slope"); print(rbind(cbind(var = "survival", equiv_boot(last$o_surv, last$p_surv, last$pid)[, ..cols]), cbind(var = "QMD", equiv_boot(last$o_qmd, last$p_qmd, last$pid)[, ..cols]), cbind(var = "BA", equiv_boot(last$o_ba, last$p_ba, last$pid)[, ..cols])))
  fwrite(bt[, .(planted, h, o_surv, p_surv, o_qmd, p_qmd, o_ba, p_ba)], "out/check29_benchmark_after_thinning.csv") }
cat("29 done\n")
